# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İNSANDA SİNİR SİSTEMİNİN BÖLÜMLERİ (FB.6.3.6)</text>\n  <rect x="20" y="46" width="420" height="196" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="230" y="70" text-anchor="middle" font-size="13.5" font-weight="bold" fill="#1d4ed8">1. MERKEZİ SİNİR SİSTEMİ (Yönetim ve Değerlendirme)</text>\n  <rect x="36" y="84" width="185" height="142" rx="6" fill="#dbeafe" stroke="#2563eb"/>\n  <text x="128" y="106" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">A) Beyin (Kafatası İçinde)</text>\n  <text x="128" y="130" text-anchor="middle" font-size="11" fill="#1e3a8a">• Beyin (İstemli hareket, zekâ)</text>\n  <text x="128" y="152" text-anchor="middle" font-size="11" fill="#1e3a8a">• Beyincik (Denge ve kas uyumu)</text>\n  <text x="128" y="174" text-anchor="middle" font-size="11" fill="#1e3a8a">• Omurilik Soğanı (Hayat</text>\n  <text x="128" y="190" text-anchor="middle" font-size="11" fill="#1e3a8a">düğümü: İç organ yönetimi)</text>\n\n  <rect x="238" y="84" width="185" height="142" rx="6" fill="#e0f2fe" stroke="#0284c7"/>\n  <text x="330" y="106" text-anchor="middle" font-size="12" font-weight="bold" fill="#0369a1">B) Omurilik (Omurga İçinde)</text>\n  <text x="330" y="132" text-anchor="middle" font-size="11" fill="#0c4a6e">• Refleks davranışlarını</text>\n  <text x="330" y="148" text-anchor="middle" font-size="11" fill="#0c4a6e">yöneten merkezdir.</text>\n  <text x="330" y="172" text-anchor="middle" font-size="11" fill="#0c4a6e">• Beyin ile organlar arasında</text>\n  <text x="330" y="188" text-anchor="middle" font-size="11" fill="#0c4a6e">uyartı iletim köprüsüdür.</text>\n\n  <rect x="456" y="46" width="224" height="196" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="568" y="70" text-anchor="middle" font-size="13.5" font-weight="bold" fill="#15803d">2. ÇEVRESEL SİNİR SİSTEMİ</text>\n  <text x="568" y="98" text-anchor="middle" font-size="11.5" fill="#14532d">• Vücudun her yanını ağ gibi</text>\n  <text x="568" y="116" text-anchor="middle" font-size="11.5" fill="#14532d">saran milyonlarca sinir</text>\n  <text x="568" y="134" text-anchor="middle" font-size="11.5" fill="#14532d">hücresinden (nörondan) oluşur.</text>\n  <text x="568" y="162" text-anchor="middle" font-size="11.5" fill="#14532d">• Duyu organlarından aldığı</text>\n  <text x="568" y="180" text-anchor="middle" font-size="11.5" fill="#14532d">uyartıları merkeze, merkezden</text>\n  <text x="568" y="198" text-anchor="middle" font-size="11.5" fill="#14532d">gelen cevabı organlara taşır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MERKEZİ SİNİR SİSTEMİ ORGANLARI VE TEMEL GÖREVLERİ</text>\n  <rect x="18" y="48" width="160" height="192" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="98" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. Beyin</text>\n  <text x="98" y="96" text-anchor="middle" font-size="10.5" fill="#1e3a8a">• Öğrenme, hafıza, düşünme</text>\n  <text x="98" y="114" text-anchor="middle" font-size="10.5" fill="#1e3a8a">• 5 duyu organının merkezi</text>\n  <text x="98" y="132" text-anchor="middle" font-size="10.5" fill="#1e3a8a">• Konuşma ve istemli hareket</text>\n  <text x="98" y="150" text-anchor="middle" font-size="10.5" fill="#1e3a8a">• Açlık, susuzluk, uyku</text>\n  <text x="98" y="168" text-anchor="middle" font-size="10.5" fill="#1e3a8a">• Kan basıncı ve vücut ısısı</text>\n  <text x="98" y="210" text-anchor="middle" font-size="10" font-weight="bold" fill="#2563eb">En büyük sinir merkezi</text>\n\n  <rect x="186" y="48" width="160" height="192" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="266" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. Beyincik</text>\n  <text x="266" y="96" text-anchor="middle" font-size="10.5" fill="#14532d">• Vücudun kas uyumu ve</text>\n  <text x="266" y="114" text-anchor="middle" font-size="10.5" fill="#14532d">hareket dengesini sağlar.</text>\n  <text x="266" y="138" text-anchor="middle" font-size="10.5" fill="#14532d">• Kulaktaki yarım daire</text>\n  <text x="266" y="156" text-anchor="middle" font-size="10.5" fill="#14532d">kanallarıyla birlikte çalışır.</text>\n  <text x="266" y="180" text-anchor="middle" font-size="10.5" fill="#14532d">• İp cambazı ve bebeklerin</text>\n  <text x="266" y="210" text-anchor="middle" font-size="10" font-weight="bold" fill="#166534">Denge Merkezi (Hayat Ağacı)</text>\n\n  <rect x="354" y="48" width="160" height="192" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="434" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">3. Omurilik Soğanı</text>\n  <text x="434" y="96" text-anchor="middle" font-size="10.5" fill="#713f12">• Solunum, dolaşım, boşaltım</text>\n  <text x="434" y="114" text-anchor="middle" font-size="10.5" fill="#713f12">ve sindirim sistemlerini</text>\n  <text x="434" y="132" text-anchor="middle" font-size="10.5" fill="#713f12">istemsiz olarak yönetir.</text>\n  <text x="434" y="156" text-anchor="middle" font-size="10.5" fill="#713f12">• Yutma, çiğneme, öksürme,</text>\n  <text x="434" y="174" text-anchor="middle" font-size="10.5" fill="#713f12">hapşırma ve kusmayı yönetir.</text>\n  <text x="434" y="210" text-anchor="middle" font-size="10" font-weight="bold" fill="#854d0e">Hayat Düğümü</text>\n\n  <rect x="522" y="48" width="160" height="192" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="602" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#be185d">4. Omurilik</text>\n  <text x="602" y="96" text-anchor="middle" font-size="10.5" fill="#9d174d">• Doğuştan ve sonradan</text>\n  <text x="602" y="114" text-anchor="middle" font-size="10.5" fill="#9d174d">kazanılan refleksleri yönetir.</text>\n  <text x="602" y="138" text-anchor="middle" font-size="10.5" fill="#9d174d">• Beyin ile çevresel sinirler</text>\n  <text x="602" y="156" text-anchor="middle" font-size="10.5" fill="#9d174d">arasında iletim sağlar.</text>\n  <text x="602" y="180" text-anchor="middle" font-size="10.5" fill="#9d174d">• İğne batan elin çekilmesi</text>\n  <text x="602" y="210" text-anchor="middle" font-size="10" font-weight="bold" fill="#be185d">Refleks ve İletim Merkezi</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">UYARTI İLETİM ZİNCİRİ VE REFLEKS ÇEŞİTLERİ</text>\n  <rect x="25" y="48" width="650" height="82" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="350" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">1. Sinir Sisteminde Uyartıdan Tepkiye İletim Sırası</text>\n  <text x="350" y="98" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">Uyarı (Ses/Işık/Isı) ➔ Duyu Organı (Almaçlar) ➔ Uyartı Mesajı ➔ Merkezi Sinir Sistemi ➔ Cevap ➔ Tepki</text>\n  <text x="350" y="118" text-anchor="middle" font-size="11" fill="#334155">Çevresel sinir sistemi, uyartıları merkeze götürür ve merkezde oluşan cevabı ilgili kas veya salgı bezine iletir.</text>\n\n  <rect x="25" y="142" width="315" height="98" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="182" y="164" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">A) Doğuştan Gelen (Kalıtsal) Refleksler</text>\n  <text x="182" y="188" text-anchor="middle" font-size="11" fill="#1e3a8a">• İğne batan veya sıcak cisme değen elin çekilmesi</text>\n  <text x="182" y="206" text-anchor="middle" font-size="11" fill="#1e3a8a">• Parlak ışıkta göz bebeğinin küçülmesi</text>\n  <text x="182" y="224" text-anchor="middle" font-size="11" fill="#1e3a8a">• Yeni doğan bebeğin emme refleksi, diz kapağı</text>\n\n  <rect x="360" y="142" width="315" height="98" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="517" y="164" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#7e22ce">B) Sonradan Kazanılan (Şartlı) Refleksler</text>\n  <text x="517" y="188" text-anchor="middle" font-size="11" fill="#581c87">• Önce beyinle öğrenilir, sonra omurilik devralır:</text>\n  <text x="517" y="206" text-anchor="middle" font-size="11" fill="#581c87">• Bisiklet sürmek, yüzmek, örgü örmek, dans etmek</text>\n  <text x="517" y="224" text-anchor="middle" font-size="11" fill="#581c87">• Limon görünce ağzın sulanması</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
